# jogos de literatura
rod = []
autores = sorted({x['autor'] for x in L})
for x in L:
    err = random.sample([a for a in autores if a != x['autor']], 3); ops = err + [x['autor']]; random.shuffle(ops)
    rod.append({'enunciado': '📖 Quem escreveu?', 'destaque': f'“{x["obra"]}” ({x["ano"]})', 'opcoes': ops, 'correta': x['autor'], 'explica': f'{x["obra"]} é de {x["autor"]} ({x["escola"]}). {x["resumo"]}'})
for x in L:
    outros = random.sample([y for y in L if y['obra'] != x['obra'] and not set(y['temas']) & set(x['temas'])], 3)
    ops = [f'{y["obra"]} ({y["autor"]})' for y in outros] + [f'{x["obra"]} ({x["autor"]})']; random.shuffle(ops)
    rod.append({'enunciado': '✍️ Repertório: qual obra combina com o tema?', 'destaque': 'Tema: ' + x['temas'][0], 'opcoes': ops, 'correta': f'{x["obra"]} ({x["autor"]})', 'explica': x['uso']})
json.dump({'titulo': 'Literatura clássica brasileira para a redação', 'emoji': '📖', 'instrucao': 'Escolha a resposta certa.', 'rodadas': rod}, open(os.path.join(RAIZ, 'dados', 'red-literatura.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
rr = []
for x in R:
    outros = random.sample([y for y in R if not set(y['eixos']) & set(x['eixos'])], 3)
    ops = [y['titulo'] + ' (' + y['autor'] + ')' for y in outros] + [x['titulo'] + ' (' + x['autor'] + ')']; random.shuffle(ops)
    rr.append({'enunciado': '📚 Qual repertório combina com um texto sobre…', 'destaque': x['eixos'][0], 'opcoes': ops, 'correta': x['titulo'] + ' (' + x['autor'] + ')', 'explica': x['ideia'] + ' Exemplo de uso: ' + x['uso']})
json.dump({'titulo': 'Repertório para a redação do ENEM', 'emoji': '📚', 'instrucao': 'Escolha o repertório que combina com o tema.', 'rodadas': rr}, open(os.path.join(RAIZ, 'dados', 'red-repertorio-enem.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
pares = random.sample(L, 14)
json.dump({'titulo': 'Memória: obra e autor (literatura brasileira)', 'relacao': 'obra e autor', 'pares': [{'a': x['obra'], 'b': x['autor'], 'explica': f'{x["obra"]} ({x["ano"]}), de {x["autor"]}.'} for x in pares]}, open(os.path.join(RAIZ, 'dados', 'memoria-literatura.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
ind = json.load(open(os.path.join(RAIZ, 'dados', 'indice.json'), encoding='utf-8'))
def add(cat, e):
    l = ind.setdefault(cat, []); l[:] = [y for y in l if y['arquivo'] != e['arquivo']]; l.append(e)
add('escolha-red', {'arquivo': 'red-literatura.json', 'titulo': '📖 Literatura clássica brasileira para a redação', 'qtd': len(rod)})
add('escolha-red', {'arquivo': 'red-repertorio-enem.json', 'titulo': '📚 Repertório para a redação do ENEM', 'qtd': len(rr)})
add('memoria', {'arquivo': 'memoria-literatura.json', 'titulo': '📖 Obra e autor (literatura brasileira)'})
